/* Decode the request of n bytes at req, which came on ch, call its handler,
 * encode the reply into rep (IDLTEST_REP_MAX bytes) and the handles it carries
 * into rhs (IDL_REP_HANDLES slots; *rhn of them). Returns the reply's
 * length: 0 means no reply (the request has no txid, or a `later`
 * handler answers it itself). No I/O; the caller sends the reply with the
 * handles, or closes them if it can't. */
static inline uint32_t idltest_dispatch_on(handle_t ch, const struct idltest_ops *ops, void *ctx,
                                           const void *req, uint32_t n, void *rep, handle_t *rhs,
                                           uint32_t *rhn)
{
    struct idl_rep_hdr *idl_h = (struct idl_rep_hdr *)rep;
    *rhn = 0;
    (void)rhs;
    if (n < sizeof(uint32_t))
        return 0;
    idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
    idl_h->status = ERR_INVALID_ARGS;
    if (n < sizeof(struct idl_req_hdr))
        return sizeof(*idl_h);
    switch (((const struct idl_req_hdr *)req)->ordinal) {
    case IDLTEST_ECHO: {
        const struct idltest_echo_req *idl_q = (const struct idltest_echo_req *)req;
        struct idltest_echo_rep *idl_r = (struct idltest_echo_rep *)rep;
        uint32_t out_value = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->echo) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->echo(ctx, idl_q->value, &out_value);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->value = out_value;
        return sizeof(*idl_r);
    }
    case IDLTEST_WAIT: {
        const struct idltest_wait_req *idl_q = (const struct idltest_wait_req *)req;
        struct idltest_wait_rep *idl_r = (struct idltest_wait_rep *)rep;
        uint32_t out_key = 0;
        uint32_t out_order = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->wait) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        struct idl_txn idl_txn = { ch, idl_h->txid };
        status_t idl_st = ops->wait(ctx, idl_txn, idl_q->key, &out_key, &out_order);
        /* IDL_LATER: the handler answers with idltest_reply_wait. */
        if (idl_st == IDL_LATER)
            return 0;
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->key = out_key;
        idl_r->order = out_order;
        return sizeof(*idl_r);
    }
    case IDLTEST_RELEASE: {
        const struct idltest_release_req *idl_q = (const struct idltest_release_req *)req;
        struct idltest_release_rep *idl_r = (struct idltest_release_rep *)rep;
        uint32_t out_woken = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->release) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->release(ctx, idl_q->key, &out_woken);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->woken = out_woken;
        return sizeof(*idl_r);
    }
    case IDLTEST_MAKE_VMO: {
        const struct idltest_make_vmo_req *idl_q = (const struct idltest_make_vmo_req *)req;
        struct idltest_make_vmo_rep *idl_r = (struct idltest_make_vmo_rep *)rep;
        handle_t out_vmo = HANDLE_INVALID;
        uint32_t out_size_back = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->make_vmo) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        struct idl_txn idl_txn = { ch, idl_h->txid };
        status_t idl_st = ops->make_vmo(ctx, idl_txn, idl_q->key, idl_q->size, &out_vmo, &out_size_back);
        /* IDL_LATER: the handler answers with idltest_reply_make_vmo. */
        if (idl_st == IDL_LATER) {
            if (out_vmo != HANDLE_INVALID)
                drv_handle_close(out_vmo);
            return 0;
        }
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_vmo != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_vmo != HANDLE_INVALID)
                drv_handle_close(out_vmo);
            return sizeof(*idl_h);
        }
        rhs[0] = out_vmo;
        *rhn = 1;
        idl_r->size_back = out_size_back;
        return sizeof(*idl_r);
    }
    }
    idl_h->status = ERR_NOT_SUPPORTED;
    return sizeof(*idl_h);
}

/* idltest_dispatch_on without the channel (a `later` handler's txn then has none: use idltest_dispatch_on). */
static inline uint32_t idltest_dispatch(const struct idltest_ops *ops, void *ctx, const void *req, uint32_t n,
                                        void *rep, handle_t *rhs, uint32_t *rhn)
{
    return idltest_dispatch_on(HANDLE_INVALID, ops, ctx, req, n, rep, rhs, rhn);
}

/* Take one message off ch and answer it. OK once a message was handled
 * (its reply may still have been dropped: the client is gone, or never
 * called); otherwise drv_channel_read's status: ERR_SHOULD_WAIT when
 * nothing is queued, ERR_PEER_CLOSED when the client is gone for good. */
static inline status_t idltest_serve_one(handle_t ch, const struct idltest_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[IDLTEST_REQ_MAX];
    _Alignas(8) uint8_t idl_r[IDLTEST_REP_MAX];
    handle_t idl_hs[IDL_READ_HANDLES];
    uint32_t idl_n = 0, idl_nh = 0;
    status_t idl_st = drv_channel_read(ch, idl_q, sizeof(idl_q), &idl_n, idl_hs, IDL_READ_HANDLES,
                                       &idl_nh);
    if (idl_st == ERR_BUFFER_TOO_SMALL)
        return idl_drain(ch, idl_n, idl_nh);
    if (idl_st != OK)
        return idl_st;
    if (idl_nh) {
        idl_close_all(idl_hs, idl_nh);
        idl_reply_status(ch, idl_q, idl_n, ERR_INVALID_ARGS);
        return OK;
    }
    handle_t idl_rhs[IDL_REP_HANDLES];
    uint32_t idl_rhn = 0;
    uint32_t idl_rn = idltest_dispatch_on(ch, ops, ctx, idl_q, idl_n, idl_r, idl_rhs, &idl_rhn);
    if (!idl_rn || drv_channel_write(ch, idl_r, idl_rn, idl_rhs, idl_rhn) != OK)
        idl_close_all(idl_rhs, idl_rhn);   /* not sent: they're still ours */
    return OK;
}

/* Serve ch until the client closes it (OK), or a wait or read fails
 * (that status: ERR_CANCELED when the driver is being killed). Each reply
 * goes out in the system call that takes the next request
 * (idl_serve_next). */
static inline status_t idltest_serve(handle_t ch, const struct idltest_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[IDLTEST_REQ_MAX];
    _Alignas(8) uint8_t idl_r[IDLTEST_REP_MAX];
    handle_t idl_rhs[IDL_REP_HANDLES];
    struct idl_serve idl_s = {
        .ch = ch, .q = idl_q, .qcap = sizeof(idl_q), .r = idl_r, .rhs = idl_rhs,
    };
    for (;;) {
        status_t idl_st = idl_serve_next(&idl_s);
        if (idl_st == ERR_PEER_CLOSED)
            return OK;
        if (idl_st != OK)
            return idl_st;
        idl_s.rn = idltest_dispatch_on(ch, ops, ctx, idl_q, idl_s.n, idl_r, idl_rhs, &idl_s.rhn);
    }
}
